from pathlib import Path
import json
h=Path.home()
t='DEV-PRED-A2Z-R4P3-SELECTION-RETRY-20261008-E208'
p=h/'.local/state/prediction-project-executor'/(t+'.json')
o=json.loads(p.read_text()) if p.exists() else {}
r=h/'.local/share/prediction-chat-bridge/dev-task-receipts'/(t+'.log')
lines=r.read_text(errors='replace').splitlines() if r.exists() else []
matches=[]
for i,s in enumerate(lines):
 if any(z in s for z in ('ModuleNotFoundError:', 'FileNotFoundError:', 'AssertionError:', 'ImportError:', 'KeyError:', 'TypeError:', 'SyntaxError:', 'PermissionError:', 'ValueError:')):
  matches.append(s.strip())
if not matches:
 for k in ('error','detail'):
  v=o.get(k)
  if v: matches.append(str(v).replace('\n',' ')[:180])
if not matches:
 for s in lines:
  if 'ERROR=' in s and 'Traceback' not in s: matches.append(s.strip())
raise SystemExit('ROOTCAUSE='+str(matches[-1] if matches else 'UNDETERMINED')[:240])
